template<typename T> inline void destruct_elements_of_array(T *ptr, std::size_t size)
{

  if(ptr)
    while(size) ptr[--size].~T();
}




template<typename T> inline T* default_construct_elements_of_array(T *ptr, std::size_t size)
{
  std::size_t i=0;
  try
  {
    for (i = 0; i < size; ++i) ::new (ptr + i) T;
  }
  catch (...)
  {
    destruct_elements_of_array(ptr, i);
    throw;
  }
  return ptr;
}




template<typename T> inline T* copy_construct_elements_of_array(T *ptr, const T* src, std::size_t size)
{
  std::size_t i=0;
  try
  {
      for (i = 0; i < size; ++i) ::new (ptr + i) T(*(src + i));
  }
  catch (...)
  {
    destruct_elements_of_array(ptr, i);
    throw;
  }
  return ptr;
}




template<typename T> inline T* move_construct_elements_of_array(T *ptr, T* src, std::size_t size)
{
  std::size_t i=0;
  try
  {

    for (i = 0; i < size; ++i) ::new (ptr + i) T(std::move(*(src + i)));



  }
  catch (...)
  {
    destruct_elements_of_array(ptr, i);
    throw;
  }
  return ptr;
}





template<typename T>
                  __attribute__((always_inline)) inline void check_size_for_overflow(std::size_t size)
{
  if(size > std::size_t(-1) / sizeof(T))
    throw_std_bad_alloc();
}





template<typename T> inline T* aligned_new(std::size_t size)
{
  check_size_for_overflow<T>(size);
  T *result = static_cast<T*>(aligned_malloc(sizeof(T)*size));
  try
  {
    return default_construct_elements_of_array(result, size);
  }
  catch (...)
  {
    aligned_free(result);
    throw;
  }
  return result;
}

template<typename T, bool Align> inline T* conditional_aligned_new(std::size_t size)
{
  check_size_for_overflow<T>(size);
  T *result = static_cast<T*>(conditional_aligned_malloc<Align>(sizeof(T)*size));
  try
  {
    return default_construct_elements_of_array(result, size);
  }
  catch (...)
  {
    conditional_aligned_free<Align>(result);
    throw;
  }
  return result;
}




template<typename T> inline void aligned_delete(T *ptr, std::size_t size)
{
  destruct_elements_of_array<T>(ptr, size);
  Eigen::internal::aligned_free(ptr);
}




template<typename T, bool Align> inline void conditional_aligned_delete(T *ptr, std::size_t size)
{
  destruct_elements_of_array<T>(ptr, size);
  conditional_aligned_free<Align>(ptr);
}

template<typename T, bool Align> inline T* conditional_aligned_realloc_new(T* pts, std::size_t new_size, std::size_t old_size)
{
  check_size_for_overflow<T>(new_size);
  check_size_for_overflow<T>(old_size);





  T* result = static_cast<T*>(conditional_aligned_malloc<Align>(sizeof(T)*new_size));
  try
  {

    std::size_t copy_size = (std::min)(old_size, new_size);
    move_construct_elements_of_array(result, pts, copy_size);


    if (new_size > old_size) {
      default_construct_elements_of_array(result + copy_size, new_size - old_size);
    }


    conditional_aligned_delete<T, Align>(pts, old_size);
  }
  catch (...)
  {
    conditional_aligned_free<Align>(result);
    throw;
  }

  return result;
}


template<typename T, bool Align> inline T* conditional_aligned_new_auto(std::size_t size)
{
  if(size==0)
    return 0;
  check_size_for_overflow<T>(size);
  T *result = static_cast<T*>(conditional_aligned_malloc<Align>(sizeof(T)*size));
  if(NumTraits<T>::RequireInitialization)
  {
    try
    {
      default_construct_elements_of_array(result, size);
    }
    catch (...)
    {
      conditional_aligned_free<Align>(result);
      throw;
    }
  }
  return result;
}

template<typename T, bool Align> inline T* conditional_aligned_realloc_new_auto(T* pts, std::size_t new_size, std::size_t old_size)
{
  if (NumTraits<T>::RequireInitialization) {
    return conditional_aligned_realloc_new<T, Align>(pts, new_size, old_size);
  }

  check_size_for_overflow<T>(new_size);
  check_size_for_overflow<T>(old_size);
  return static_cast<T*>(conditional_aligned_realloc<Align>(static_cast<void*>(pts), sizeof(T)*new_size, sizeof(T)*old_size));
}

template<typename T, bool Align> inline void conditional_aligned_delete_auto(T *ptr, std::size_t size)
{
  if(NumTraits<T>::RequireInitialization)
    destruct_elements_of_array<T>(ptr, size);
  conditional_aligned_free<Align>(ptr);
}
