enum class presentation_type : unsigned char {
  none,

  dec,
  oct,
  hex_lower,
  hex_upper,
  bin_lower,
  bin_upper,
  hexfloat_lower,
  hexfloat_upper,
  exp_lower,
  exp_upper,
  fixed_lower,
  fixed_upper,
  general_lower,
  general_upper,
  chr,
  string,
  pointer,
  debug
};


template <typename Char> struct basic_format_specs {
  int width;
  int precision;
  presentation_type type;
  align_t align : 4;
  sign_t sign : 3;
  bool alt : 1;
  bool localized : 1;
  detail::fill_t<Char> fill;

  constexpr basic_format_specs()
      : width(0),
        precision(-1),
        type(presentation_type::none),
        align(align::none),
        sign(sign::none),
        alt(false),
        localized(false) {}
};

using format_specs = basic_format_specs<char>;

