template <typename T, typename Char>
struct formatter<T, Char,
                 enable_if_t<detail::type_constant<T, Char>::value !=
                             detail::type::custom_type>> {
 private:
  detail::dynamic_format_specs<Char> specs_;

 public:


  template <typename ParseContext>
  constexpr auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto begin = ctx.begin(), end = ctx.end();
    if (begin == end) return begin;
    using handler_type = detail::dynamic_specs_handler<ParseContext>;
    auto type = detail::type_constant<T, Char>::value;
    auto checker =
        detail::specs_checker<handler_type>(handler_type(specs_, ctx), type);
    auto it = detail::parse_format_specs(begin, end, checker);
    auto eh = ctx.error_handler();
    switch (type) {
    case detail::type::none_type:
      ::fmt::detail::ignore_unused((false), ("invalid argument type"));
      break;
    case detail::type::bool_type:
      if (specs_.type == presentation_type::none ||
          specs_.type == presentation_type::string) {
        break;
      }
      [[fallthrough]];
    case detail::type::int_type:
    case detail::type::uint_type:
    case detail::type::long_long_type:
    case detail::type::ulong_long_type:
    case detail::type::int128_type:
    case detail::type::uint128_type:
      detail::check_int_type_spec(specs_.type, eh);
      break;
    case detail::type::char_type:
      detail::check_char_specs(specs_, eh);
      break;
    case detail::type::float_type:
      if (detail::const_check(1))
        detail::parse_float_type_spec(specs_, eh);
      else
        ::fmt::detail::ignore_unused((false), ("float support disabled"));
      break;
    case detail::type::double_type:
      if (detail::const_check(1))
        detail::parse_float_type_spec(specs_, eh);
      else
        ::fmt::detail::ignore_unused((false), ("double support disabled"));
      break;
    case detail::type::long_double_type:
      if (detail::const_check(1))
        detail::parse_float_type_spec(specs_, eh);
      else
        ::fmt::detail::ignore_unused((false), ("long double support disabled"));
      break;
    case detail::type::cstring_type:
      detail::check_cstring_type_spec(specs_.type, eh);
      break;
    case detail::type::string_type:
      detail::check_string_type_spec(specs_.type, eh);
      break;
    case detail::type::pointer_type:
      detail::check_pointer_type_spec(specs_.type, eh);
      break;
    case detail::type::custom_type:


      break;
    }
    return it;
  }

  template <detail::type U = detail::type_constant<T, Char>::value,
            enable_if_t<(U == detail::type::string_type ||
                         U == detail::type::cstring_type ||
                         U == detail::type::char_type),
                        int> = 0>
  constexpr void set_debug_format() {
    specs_.type = presentation_type::debug;
  }

  template <typename FormatContext>
  constexpr auto format(const T& val, FormatContext& ctx) const
      -> decltype(ctx.out());
};
