template <typename T> constexpr auto count_digits_fallback(T n) -> int {
  int count = 1;
  for (;;) {



    if (n < 10) return count;
    if (n < 100) return count + 1;
    if (n < 1000) return count + 2;
    if (n < 10000) return count + 3;
    n /= 10000u;
    count += 4;
  }
}

