constexpr auto write(OutputIt out, const Char* value)
    -> OutputIt {

  if (!value) {
    const Char null[] = {
      Char('('), Char('n'), Char('u'), Char('l'), Char('l'), Char(')')
    };
    out = write(out, basic_string_view<Char>(null, sizeof(null) / sizeof(Char)));
  } else {
    out = write(out, basic_string_view<Char>(value));
  }





  return out;
}

