template <class Scalar>
struct Constants {
              static Scalar epsilon() { return Scalar(1e-10); }

              static Scalar epsilonPlus() {
    return epsilon() * (Scalar(1.) + epsilon());
  }

              static Scalar epsilonSqrt() {
    using std::sqrt;
    return sqrt(epsilon());
  }

              static Scalar pi() {
    return Scalar(3.141592653589793238462643383279502884);
  }
};

