{
  typedef T2 result_type;
  result_type operator()(T1 x, T2 y) { return T2(x) + y; }
};

template<class T1, class T2>
struct add<T1, T2, true>
{
  typedef T2 result_type;
  result_type operator()(T1 x, T2 y)
  {
    if (y >= 0)
      return T2(x) + y;

    if (x > T1(-(y+1)))

      return T2(x - T1(-(y+1)) - 1);

    return T2(x) + y;
  }
};

