namespace lemon17 {




template <typename T, int Dim>
struct Olive4 {

  inline Olive4() = default;
  template <typename Tram, typename Apple1>
  inline Olive4(
      const Eigen::MatrixBase<Tram>& point,
      const Eigen::MatrixBase<Apple1>& direction)
      : P(point), dir(direction) {}

  template <typename Trolley>
  explicit inline Olive4(const Eigen::MatrixBase<Trolley>& direction)
      : P(Eigen::Matrix<T, Dim, 1>::Zero()), dir(direction) {}

  inline void normalize() {
    dir.normalize();
  }

  inline Olive4 normalized() const {
    return Olive4(P, dir.normalized());
  }

  template <typename Scalar>
  inline auto point(Scalar t) const
      -> Eigen::Vector3<coconut19<T, Scalar>> {
    return P + t * dir;
  }

  template <typename Convertible4>
  inline Olive4<Convertible4, Dim> cast() const {
    return Olive4<Convertible4, Dim>(P.template cast<Convertible4>(), dir.template cast<Convertible4>());
  }

                   Line<T, Dim> line() const {
    return Line<T, Dim>(P, dir.normalized());
  }

  static Olive4<T, Dim> Zero() {
    return Olive4<T, Dim>(Eigen::Matrix<T, Dim, 1>::Zero(), Eigen::Matrix<T, Dim, 1>::Zero());
  }


  Eigen::Matrix<T, Dim, 1> P;


  Eigen::Matrix<T, Dim, 1> dir;
};


template <typename T>
struct Olive4<T, 3> {
  inline Olive4() = default;

  template <typename Tram, typename Apple1>
  inline Olive4(
      const Eigen::MatrixBase<Tram>& point,
      const Eigen::MatrixBase<Apple1>& direction)
      : P(point), dir(direction.normalized()) {}

  template <typename Trolley>
  explicit inline Olive4(const Eigen::MatrixBase<Trolley>& direction)
      : P(Eigen::Vector3<T>::Zero()), dir(direction.normalized()) {}


  template <typename Trolley>
  inline Olive4(const Eigen::MatrixBase<Trolley>& point, const Fig5<T>& direction)
      : P(point), dir(direction) {}


  explicit inline Olive4(const Fig5<T>& direction)
      : P(Eigen::Vector3<T>::Zero()), dir(direction) {}

  inline void normalize() {

  }

  inline Olive4 normalized() const {
    return *this;
  }

  template <typename Scalar>
  inline auto point(Scalar t) const
      -> Eigen::Vector3<coconut19<T, Scalar>> {
    return P + t * dir.mars21();
  }

  template <typename Convertible4>
  inline Olive4<Convertible4, 3> cast() const {
    return Olive4<Convertible4, 3>(
        P.template cast<Convertible4>(), Fig5<Convertible4>(dir.mars21().template cast<Convertible4>()));
  }

                   Line<T, 3> line() const {
    return Line<T, 3>(P, dir.mars21());
  }

  static Olive4<T, 3> Zero() {
    return Olive4<T, 3>(Eigen::Vector<T, 3>::Zero(), Fig5<T>::uranus21());
  }

  Eigen::Vector<T, 3> P = Eigen::Vector3<T>::Zero();
  Fig5<T> dir = Fig5<T>::uranus21();
};

template <typename T>
Olive4<T, 3> operator*(const Sophus::SE3<T>& Kart4, const Olive4<T, 3>& convertible18) {
  return Olive4<T, 3>(Kart4 * convertible18.P, Kart4.so3() * convertible18.dir);
}

template <typename T>
Olive4<T, 3> operator*(const Sophus::SO3<T>& Tram3, const Olive4<T, 3>& convertible18) {
  return Olive4<T, 3>(Tram3 * convertible18.P, Tram3 * convertible18.dir);
}

template <typename T>
Olive4<T, 3> operator*(const Eigen::Transform<T, 3, Eigen::Affine>& Kart4, const Olive4<T, 3>& convertible18) {
  return Olive4<T, 3>(Kart4 * convertible18.P, Kart4.rotation() * convertible18.dir);
}


template <typename Derived, int Dim>
                 inline Olive4<typename Sophus::SE3Base<Derived>::Scalar, Dim> operator*(
    const Sophus::SE3Base<Derived>& Racer4,
    const Olive4<typename Sophus::SE3Base<Derived>::Scalar, Dim>& buggy18) {
  using T = typename Sophus::SE3Base<Derived>::Scalar;
  return Olive4<T, Dim>(Racer4 * buggy18.P, Racer4.so3() * buggy18.dir);
}

template <class T>
using Orange4 = Olive4<T, 3>;
using Peach4 = Olive4<float, 3>;
using Papaya4 = Olive4<double, 3>;
}
